// Author: MiYu. DotA rune storage and release exercise real source scripts and unit effects.
#include "session.h"
#include "setup.h"
#include <array>
#include <bit>
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc!=4)throw std::runtime_error("Usage: war3_dota_rune_tests <data-root> <dota-map> <regen|damage|illusion>");std::wstring mode=argv[3];const char* rune=mode==L"regen"?"I008":mode==L"damage"?"I00K":mode==L"illusion"?"I007":nullptr;if(!rune)throw std::runtime_error("Unknown rune mode");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;MapStrings strings;if(auto data=archives.readCandidates({"war3map.wts"},ArchiveScope::Map))strings=mapStrings(data->bytes);ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info,std::move(strings));session.attachWorld(std::move(world));session.audioSimulationClock();session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto require=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};auto code=[&](const char* value){return vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(value)));};auto real=[&](int value){return vm.real(jass::Real::fromInteger(value));};auto number=[](jass::Real value){return std::bit_cast<float>(value.bits());};auto player=session.localPlayer().value_or(0);auto hero=vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000+player),code("Hpal"),real(-4000),real(0),real(0)});require(hero.bits && session.units().contains(hero.bits),"Hero creation failed");auto u=session.units().at(hero.bits);u->acquireRange={};u->healthRegen=0;u->manaRegen=0;u->life=jass::Real::fromInteger(200);u->mana={};vm.invoke("FogEnable",std::array{vm.boolean(false)});vm.invoke("FogMaskEnable",std::array{vm.boolean(false)});auto ground=vm.invoke("CreateItem",std::array{code(rune),real(-3900),real(0)});auto bottle=vm.invoke("UnitAddItemById",std::array{hero,code("I0AM")});require(ground.bits && bottle.bits && session.useItem(hero.bits,bottle.bits,ground.bits),"Bottle could not target rune");for(int i=0;i<4;++i)session.advance(.25);require(!session.items().contains(ground.bits),"Rune remained after storage");std::uint32_t stored=0;for(auto id:u->inventory)if(id && session.items().contains(id))stored=id;require(stored && stored!=bottle.bits,"Stored rune bottle missing");auto initial=session.unitCombatDisplay(hero.bits);require(initial.has_value(),"Hero combat display missing");auto minimum=initial->weapons[0].minimum;require(session.useItem(hero.bits,stored),"Stored rune use rejected");for(int i=0;i<4;++i)session.advance(.25);bool refilled=false;for(auto id:u->inventory)if(id && session.items().contains(id) && session.items().at(id)->type==ObjectData::code("I0AP"))refilled=true;require(refilled,"Bottle did not refill after rune use");for(auto& [id,item]:session.items())require(item->type!=ObjectData::code(rune) || item->holder,"Released rune remained on the ground");
        if(mode==L"regen")require(number(u->life)>290 && number(u->mana)>50,"Regeneration rune did not restore health and mana");else if(mode==L"damage"){auto combat=session.unitCombatDisplay(hero.bits);require(combat && combat->weapons[0].minimum>minimum && u->spellBonus(&UnitBuff::damageBonus)>.99f,"Damage rune did not affect weapon damage");}else{unsigned count=0;for(auto& [id,unit]:session.units())if(unit->illusion && unit->illusionOriginal==hero.bits){++count;require(unit->damageDealt==.35f && unit->damageTaken==2.f && unit->timedLife && unit->timedLife->duration==75,"Rune illusion source parameters differ");}require(count==2,"Illusion rune did not create two illusions");}require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS rune_storage_release_and_effect\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
